package dashboard.enterprise.agent.connector.provider;
import dashboard.enterprise.agent.connector.model.*; import dashboard.enterprise.agent.model.AgentContext;
import java.util.*;
public final class ReplayEnterpriseConnectorProvider implements EnterpriseConnectorProvider { private final ConnectorDefinition definition; private final ConnectorConnection connection; private final int priority; private final Map<String,Map<String,Object>> outputs;
 public ReplayEnterpriseConnectorProvider(String id,String provider,int priority,List<String> capabilities,Map<String,Map<String,Object>> outputs){this.definition=new ConnectorDefinition("mapaf.connector.definition/v1",id,id,provider,ConnectorMode.REPLAY,capabilities,List.of());this.connection=new ConnectorConnection("mapaf.connector.connection/v1",id+"-connection","replay://"+id,ConnectorMode.REPLAY,Map.of());this.priority=priority;this.outputs=Map.copyOf(outputs);}
 public ConnectorDefinition definition(){return definition;} public ConnectorConnection connection(){return connection;} public int priority(){return priority;} public ConnectorHealth health(){return new ConnectorHealth("mapaf.connector.health/v1",definition.connectorId(),ConnectorStatus.HEALTHY,"Replay connector ready.",List.of(connection.endpoint()));}
 public ConnectorResponse invoke(AgentContext context,ConnectorRequest request){if(!supports(request.capabilityId()))throw new IllegalArgumentException("Unsupported capability: "+request.capabilityId());return new ConnectorResponse("mapaf.connector.response/v1",request.requestId(),definition.connectorId(),true,"Replay capability completed.",List.of(connection.endpoint()),outputs.getOrDefault(request.capabilityId(),Map.of()));}}
